        y = 7'b0000010;
        w = 0; check_outputs(1'b0, 1'b0); // Next is C
        w = 1; check_outputs(1'b0, 1'b1); // Next is D (y[3]=1)

        // Test State C (y[2] = 1'b1):
        // C --0--> E (y[4]), C --1--> D (y[3])
        y = 7'b0000100;
        w = 0; check_outputs(1'b0, 1'b0); // Next is E
        w = 1; check_outputs(1'b0, 1'b1); // Next is D (y[3]=1)

        // Test State D (y[3] = 1'b1):
