        y = 7'b0001000;
        w = 0; check_outputs(1'b0, 1'b0);
        w = 1; check_outputs(1'b0, 1'b0);

        // Test State E (y[4] = 1'b1):
        // E --0--> E (y[4]), E --1--> D (y[3])
        y = 7'b0010000;
        w = 0; check_outputs(1'b0, 1'b0);
        w = 1; check_outputs(1'b0, 1'b1); // Next is D (y[3]=1)

        // Test State F (y[5] = 1'b1):
        // F --0--> C (y[2]), F --1--> D (y[3])
        y = 7'b0100000;
        w = 0; check_outputs(1'b0, 1'b0);
        w = 1; check_outputs(1'b0, 1'b1); // Next is D (y[3]=1)

        // Final result check
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
